sys_script.script:
(function executeRule(current, previous) {

    var status = current.getValue('milestone_status');
    var isActive = current.active == true;

    // Pending and In Progress milestones must remain Active.
    if ((status == 'Pending' || status == 'In Progress') &&
        !isActive) {

        gs.addErrorMessage(
            'Pending or In Progress milestones must be Active.'
        );

        current.setAbortAction(true);
        return;
    }

    // Completed and Cancelled milestones must be Inactive.
    if ((status == 'Completed' || status == 'Cancelled') &&
        isActive) {

        gs.addErrorMessage(
            'Completed or Cancelled milestones must be Inactive.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
